// app/page.tsx
import { CarFront, Users, MapPin } from 'lucide-react';
// 🌟 引入我們剛剛寫好的 Supabase 開鎖工具
import { supabase } from '../lib/supabase';

// 🌟 加上 async，讓這個頁面具備等待資料庫回應的能力
export default async function DashboardHome() {
  
  // 1. 抓取「系統收錄車場總數」 (計算 carparks 資料表的總行數)
  const { count: totalCarparks } = await supabase
    .from('carparks')
    .select('*', { count: 'exact', head: true });

  // 2. 抓取「待審核用戶上傳」 (假設 status 為 'pending'，如果你的字眼不同可以修改這裡)
  const { count: pendingCarparks } = await supabase
    .from('carparks')
    .select('*', { count: 'exact', head: true })
    .eq('status', 'pending');

  // 3. 抓取「註冊會員總數」 (計算 profiles 資料表的總行數)
  const { count: totalUsers } = await supabase
    .from('profiles')
    .select('*', { count: 'exact', head: true });

  return (
    <div className="p-8 bg-slate-50 min-h-screen">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-slate-800">iPARK HK 管理後台</h1>
        <p className="text-slate-500 mt-2">歡迎回來，這是目前的系統即時數據。</p>
      </div>
      
      {/* 📊 數據卡片區塊 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        
        {/* 卡片 1 */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center">
          <div className="p-4 bg-blue-100 rounded-lg mr-4">
            <MapPin className="text-blue-600" size={28} />
          </div>
          <div>
            <p className="text-sm text-slate-500 font-medium">系統收錄車場總數</p>
            {/* 🌟 顯示真實數據，如果出錯則顯示 0 */}
            <h3 className="text-3xl font-bold text-slate-800 mt-1">{totalCarparks || 0}</h3>
          </div>
        </div>

        {/* 卡片 2 */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center">
          <div className="p-4 bg-yellow-100 rounded-lg mr-4">
            <CarFront className="text-yellow-600" size={28} />
          </div>
          <div>
            <p className="text-sm text-slate-500 font-medium">待審核用戶上傳</p>
            <h3 className="text-3xl font-bold text-slate-800 mt-1">{pendingCarparks || 0}</h3>
          </div>
        </div>

        {/* 卡片 3 */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center">
          <div className="p-4 bg-purple-100 rounded-lg mr-4">
            <Users className="text-purple-600" size={28} />
          </div>
          <div>
            <p className="text-sm text-slate-500 font-medium">註冊會員總數</p>
            <h3 className="text-3xl font-bold text-slate-800 mt-1">{totalUsers || 0}</h3>
          </div>
        </div>

      </div>
    </div>
  );
}